CREATE TABLE IF NOT EXISTS agents (slug text PRIMARY KEY, name text NOT NULL, category text NOT NULL, description text NOT NULL, license text NOT NULL DEFAULT 'MIT', source_url text, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published','archived')), test_status text NOT NULL DEFAULT 'not_tested', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS submissions (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name text NOT NULL CHECK (length(name) BETWEEN 2 AND 100), repository_url text NOT NULL CHECK (length(repository_url) <= 300), category text NOT NULL, description text NOT NULL CHECK (length(description) BETWEEN 20 AND 2000), license text NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(repository_url));
CREATE TABLE IF NOT EXISTS agent_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, agent_slug text NOT NULL REFERENCES agents(slug), event_type text NOT NULL CHECK (event_type IN ('download','demo','deploy_click')), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS agent_events_slug_type_idx ON agent_events(agent_slug,event_type,created_at);
CREATE INDEX IF NOT EXISTS submissions_status_idx ON submissions(status,created_at);
CREATE OR REPLACE VIEW agent_metrics AS SELECT a.slug, count(e.id) FILTER (WHERE e.event_type='download') AS download_requests, count(e.id) FILTER (WHERE e.event_type='demo') AS demo_requests, count(e.id) FILTER (WHERE e.event_type='deploy_click') AS deployment_clicks FROM agents a LEFT JOIN agent_events e ON e.agent_slug=a.slug GROUP BY a.slug;
